insert into public.dc_intervention_modules(model_version_id,code,ordinal,name,scope,initial_action,output_30_days) values(m,'A1',1,'Website','Profil, katalog, kontak, dan alur pertanyaan atau pesanan.','Kumpulkan info usaha, foto produk, dan kontak yang aktif.','Satu halaman usaha dengan katalog dan cara menghubungi.') on conflict(model_version_id,code) do nothing;
insert into public.dc_intervention_modules(model_version_id,code,ordinal,name,scope,initial_action,output_30_days) values(m,'A2',2,'Branding','Identitas merek, pesan pembeda, dan panduan materi visual.','Tulis manfaat utama produk dan pilih tampilan yang konsisten.','Panduan singkat merek dan contoh materi promosi.') on conflict(model_version_id,code) do nothing;
insert into public.dc_intervention_modules(model_version_id,code,ordinal,name,scope,initial_action,output_30_days) values(m,'A3',3,'Legalitas usaha','Pemetaan kebutuhan, arsip, dan tindak lanjut administrasi yang sesuai. Bukan jaminan izin terbit.','Buat daftar dokumen yang relevan bersama pendamping.','Daftar kebutuhan, arsip, dan status tindak lanjut administrasi.') on conflict(model_version_id,code) do nothing;
insert into public.dc_intervention_modules(model_version_id,code,ordinal,name,scope,initial_action,output_30_days) values(m,'A4',4,'Digital marketing','Konten, kampanye, tindak lanjut calon pelanggan, dan pengukuran kanal.','Pilih satu kanal dan satu tujuan promosi yang bisa diukur.','Jadwal promosi, catatan tindak lanjut, dan evaluasi hasil.') on conflict(model_version_id,code) do nothing;
insert into public.dc_intervention_modules(model_version_id,code,ordinal,name,scope,initial_action,output_30_days) values(m,'A5',5,'Marketplace onboarding','Akun toko, katalog, serta alur penerimaan dan pemenuhan pesanan.','Pilih marketplace yang sesuai dan siapkan informasi produk.','Toko dengan katalog serta alur pesanan yang siap dipakai.') on conflict(model_version_id,code) do nothing;
insert into public.dc_intervention_modules(model_version_id,code,ordinal,name,scope,initial_action,output_30_days) values(m,'A6',6,'Pelatihan keuangan','Catatan transaksi, pemisahan uang, biaya, dan ringkasan keuangan.','Mulai catat uang masuk dan keluar setiap hari.','Catatan transaksi, pemisahan uang, dan ringkasan bulanan.') on conflict(model_version_id,code) do nothing;
insert into public.dc_intervention_modules(model_version_id,code,ordinal,name,scope,initial_action,output_30_days) values(m,'A7',7,'Mentoring bisnis','Sasaran, penawaran, penanggung jawab, rutinitas eksekusi, dan evaluasi.','Sepakati satu target 30 hari dan siapa yang menjalankannya.','Rencana kerja, catatan pelaksanaan, dan evaluasi bersama.') on conflict(model_version_id,code) do nothing;
